#!/usr/bin/env python3
"""Pass-through wrapper for the real claude CLI. Logs cost and usage per `claude --print` call.

Enforces the stops in the 6737 pre-registration: a call cap and a failure streak.
All paths are fixed because the runner passes a minimal environment.
"""
import json
import os
import signal
import subprocess
import sys
import time

REAL = "/home/richard/.local/bin/claude"
DIR = os.path.expanduser("~/src/scratch/eval-6737")
LABEL = os.environ.get("CAPTURE_LABEL", "run")  # not required; default "run"
if os.path.exists(os.path.join(DIR, "LABEL")):
    LABEL = open(os.path.join(DIR, "LABEL")).read().strip()
CAP = int(open(os.path.join(DIR, "CAP")).read()) if os.path.exists(os.path.join(DIR, "CAP")) else 120
STREAK_LIMIT = 5
D = os.path.join(DIR, LABEL)
os.makedirs(D, exist_ok=True)
COUNT, STREAK, TRIP, LOG = (os.path.join(D, n) for n in ("count", "streak", "TRIPPED", "calls.jsonl"))


def rd(path, default=0):
    try:
        return int(open(path).read())
    except (OSError, ValueError):
        return default


argv = sys.argv[1:]
is_model_call = "--print" in argv or "-p" in argv
if is_model_call:
    if os.path.exists(TRIP):
        sys.stderr.write("capture wrapper: tripped, refusing call\n")
        sys.exit(99)
    n = rd(COUNT)
    if n >= CAP:
        open(TRIP, "w").write(f"cap {CAP}\n")
        sys.stderr.write(f"capture wrapper: call cap {CAP} reached\n")
        sys.exit(99)
    open(COUNT, "w").write(str(n + 1))
    prompt = sys.stdin.buffer.read()
    kw = {"input": prompt}
else:
    kw = {"stdin": subprocess.DEVNULL}

proc = subprocess.Popen([REAL, *argv], stdout=subprocess.PIPE, stdin=subprocess.PIPE if is_model_call else subprocess.DEVNULL)


def forward(signum, _frame):
    try:
        proc.send_signal(signum)
    except OSError:
        pass


signal.signal(signal.SIGTERM, forward)
signal.signal(signal.SIGINT, forward)
out, _ = proc.communicate(kw.get("input"))
rc = proc.returncode
if is_model_call:
    rec = {"t": time.time(), "rc": rc, "cost": None, "usage": None, "unread": True}
    try:
        text = out.decode("utf-8", "replace")
        try:
            obj = json.loads(text)
            events = obj if isinstance(obj, list) else [obj]
        except ValueError:
            events = [json.loads(line) for line in text.splitlines() if line.strip().startswith("{")]
        for e in events:
            if isinstance(e, dict) and e.get("type") == "result":
                rec.update(cost=e.get("total_cost_usd"), usage=e.get("usage"), subtype=e.get("subtype"),
                           is_error=e.get("is_error"), unread=False)
    except Exception as ex:  # noqa: BLE001
        rec["parse_error"] = str(ex)[:200]
    open(LOG, "a").write(json.dumps(rec) + "\n")
    streak = rd(STREAK) + 1 if rc != 0 else 0
    open(STREAK, "w").write(str(streak))
    if streak >= STREAK_LIMIT:
        open(TRIP, "w").write(f"streak {streak}\n")
sys.stdout.buffer.write(out)
sys.stdout.buffer.flush()
sys.exit(rc)
